// === Tab: shader ===
function getShader(_renderer) {
	const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		varying vec2 vTexCoord;

		void main() {
			vTexCoord = aTexCoord;

			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

			gl_Position = positionVec4;
		}
	`;

	const frag = `
		precision highp float;

		varying vec2 vTexCoord;

		uniform vec3 shapes[${g_numShapes}];

		const float WIDTH = ${windowWidth}.0;
		const float HEIGHT = ${windowHeight}.0;

		#define PI 3.1415926538

		void main() {
			float x = vTexCoord.x * WIDTH;
			float y = vTexCoord.y * HEIGHT;
			float v = 0.0;
			float v_solid = 0.0;
			bool rd = false;

			float distmin = WIDTH*WIDTH + HEIGHT*HEIGHT;
			float distmax = 0.0;
			float distavg = 0.0;


			for (int i = 0; i < ${g_numShapes}; i++) {
				vec3 mtn = shapes[i];
				float dx = mtn.x - x;
				float dy = mtn.y - y;
				float r = mtn.z;
				//float sx = dx * dx;
				//float sy = dy * dy;
				float dsq = (dx*dx + dy*dy);
				distavg += dsq;
				if (dsq < distmin) distmin = dsq;
				if (dsq > distmax) distmax = dsq;

				// Paint red dot at center
				if (dsq < 15.0) rd = true;


				// Contour lines
				v += exp(-0.0001 * dsq);
				//v += exp(-0.0000008 * pow(dsq, 1.5));
				//v += -0.0000008 * pow(dsq, 1.5);

				// Fill
				v_solid += pow(r,2.0) / dsq;
			}

			distavg /= float(${g_numShapes});

			float expected_max = pow(30.0,2.0) * 4.0;
			//float cw = distmin / WIDTH; //(distmax - distmin) / distmax;
			float cw = (expected_max -distmin) / expected_max;
			float ch = distmin / HEIGHT;

			float c = sqrt(cw);
			//if (distmin < pow(45.0, 2.0)) c = 1.0;
			//else c = 0.0;
			//if (ch > cw) c = ch;

			vec4 distc = vec4(c,c,c,1.0);
			//vec4 distc = vec4((WIDTH - distmin) / WIDTH, (HEIGHT - distmin) / HEIGHT, 1.0, 1.0);

			if (1.0 > 0.0) gl_FragColor = distc;
			//if (v < 0.5) gl_FragColor = vec4(-1.0 / ((v*PI / 0.9) + 0.999), v, 1.0-v, 1.0);
			else if (rd) gl_FragColor = vec4(1.0, 0, 0, 1.0);
			else {




				// Contour
				//float value = -1.0 / (cos(v * PI / 0.1) + 0.93);
				float value = -1.0 / (cos(v * PI / 0.9) + 0.999);
				float value2 = -1.0 / (sin(v * PI / 0.9) + 0.999);



				if(value > 0.0) gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
				else if (value2 > 0.0) gl_FragColor = vec4(0.5, 0.6, 0.9, 1.0);
				// // Solid
				else if (v_solid > 1.0) gl_FragColor = vec4(2.0 - v_solid,0.5,0.8,1.0);
				else gl_FragColor = vec4(1, 1, 1, 1);


			}	


		}
	`;

	return createShader(vert, frag);
}

